  wire :a_last, 1
  wire :b_v, 1
  wire :b_g, 7
  wire :a_j, 5
  wire :p_h, 5, init: 0
  wire :p_slot, 3, init: 0
  wire :q_j, 5, init: 0
  wire :q_h, 5, init: 0
  wire :q_slot, 3, init: 0
  wire :pn_h, 5
  wire :pn_slot, 3
  wire :qn_j, 5
  wire :qn_h, 5
  wire :qn_slot, 3
  wire :ldsel, 1, init: 0
  # lw_data select: 222 LUT inputs on one FF (hw.census); split over 4 copies.
